// Rotation matrix around the X axis.
mat3 rotateX(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(1, 0, 0),
        vec3(0, c, -s),
        vec3(0, s, c)
    );
}

// Rotation matrix around the Y axis.
mat3 rotateY(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(c, 0, s),
        vec3(0, 1, 0),
        vec3(-s, 0, c)
    );
}

// Rotation matrix around the Z axis.
mat3 rotateZ(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(c, -s, 0),
        vec3(s, c, 0),
        vec3(0, 0, 1)
    );
}

// Identity matrix.
mat3 identity() {
    return mat3(
        vec3(1, 0, 0),
        vec3(0, 1, 0),
        vec3(0, 0, 1)
    );
}

// structure for colored objects
struct Surface {
    float sd; // signed distance value
    vec3 col; // color
};

// used as sphere substraction
float opSmoothUnion( float d1, float d2, float k )
{
    float h = max(k-abs(d1-d2),0.0);
    return min(d1, d2) - h*h*0.25/k;
}

Surface minWithColor(Surface obj1, Surface obj2) {
  if (obj2.sd < obj1.sd) return obj2;
  return obj1;
}

//=========================================================================== PRIMITIVES FUNCS
Surface sdBox( vec3 p, vec3 b, vec3 offset, vec3 col, mat3 transform)
{
  p = (p - offset) * transform;
  vec3 q = abs(p) - b;
  float d = length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
  return Surface(d, col);
}

Surface sdBoxPivot( vec3 p, vec3 b, vec3 offset, vec3 col, mat3 transform, vec3 pivot)
{
  p = (p - offset) * transform - pivot;
  vec3 q = abs(p) - b;
  float d = length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
  return Surface(d, col);
}

Surface sdSphere( vec3 p, float s, vec3 col )
{
  return Surface(length(p)-s, col);
}

// floor surfaces
Surface sdFloor(vec3 p, vec3 col) {
  float d = p.y + 1.;
  return Surface(d, col);
}

Surface sdFloorSphere(vec3 pF, vec3 pS, float rS, float k, vec3 col) {
  float d1 = pF.y + 1.;
  float d2 = length(pS)-rS;
  float d = -opSmoothUnion(d2,-d1,k);
  return Surface(d, col);
}

//============================================================================ OBJECTS FUNCS
Surface sdTank( vec3 p, vec3 offset, mat3 transform, float tower_dir, float tower_pitch) {
    Surface tank = sdBox(p, vec3(1.0,0.25,0.6), offset + vec3(0., 0.25, 0.), tankColorGreen, transform);
    tank = minWithColor(tank, sdBox(p, vec3(1.0,0.2,0.7), offset, tankColorBlack, transform));
    tank = minWithColor(tank, sdBox(p, vec3(0.5, 0.15, 0.6), offset + vec3(0.0, 0.675, 0.0), tankColorGreen, rotateY(tower_dir))); // tower base
    tank = minWithColor(tank, sdBoxPivot(p, vec3(0.15,0.15,0.8), offset + vec3(0.0, 0.675, 0.0), tankColorGreen, rotateY(tower_dir) * rotateX(tower_pitch), vec3(0.,0.,-0.5))); // tower gun
    //tank = minWithColor(tank, sdBox(p, vec3(0.5, 0.15, 0.6), vec3(0.0, (-1.0 + 0.25 + 0.2 + 0.15), 0.0), tankColorGreen, rotateY(tower_dir))); // tower base
    //tank = minWithColor(tank, sdBoxPivot(p, vec3(0.15,0.15,0.8), vec3(0.0, (-1.0 + 0.25 + 0.2 + 0.15), 0.0), tankColorGreen, rotateY(tower_dir) * rotateX(tower_pitch), vec3(0.,0.,-0.5))); // tower gun
    return tank;
}
Surface sdTankBot( vec3 p, vec3 offset, mat3 transform) {
    Surface tank = sdBox(p, vec3(1.0,0.25,0.6), offset + vec3(0., 0.25, 0.), tankColorGreen, transform);
    tank = minWithColor(tank, sdBox(p, vec3(1.0,0.2,0.7), offset, tankColorBlack, transform));
    tank = minWithColor(tank, sdBox(p, vec3(0.5, 0.15, 0.6), offset + vec3(0.0, 0.25+0.25+0.15, 0.0), tankColorGreen, transform)); // tower base
    tank = minWithColor(tank, sdBox(p, vec3(0.15,0.15,0.8), offset + vec3(0.0, 0.25+0.25+0.15, 1.0), tankColorGreen, transform)); // tower gun
    return tank;
}

// Function to calculate a ballistic trajectory and draw small markers
void drawTrajectory(vec3 origin, float angleYaw, float anglePitch, float velocity, vec3 color, out Surface co, vec3 p) {
    const int numSteps = 20;     // Number of points to draw on the trajectory
    const float timeStep = 0.1; // Time step between trajectory points
    const float g = 9.8;        // Gravity constant

    for (int i = 0; i < numSteps; i++) {
        float t = float(i) * timeStep;

        // Calculate position at time t
        vec3 pos = origin;
        pos.x += velocity * cos(anglePitch) * cos(angleYaw) * t;
        pos.y += velocity * sin(anglePitch) * t - 0.5 * g * t * t; // Include gravity
        pos.z += velocity * cos(anglePitch) * sin(angleYaw) * t;

        // Check if the trajectory point is near the current ray position
        if (length(p - pos) < 0.5) {
            // Draw a small box at this position
            co = minWithColor(co, sdBox(p, vec3(0.1, 0.1, 0.1), pos, color, identity()));
        }
    }
}



