    float proj_pitch = texelFetch(iChannel3, ivec2(0, 0), 0).x;
    vec3 proj_pos = texelFetch(iChannel1, ivec2(0, 0), 0).yzw;
    // if shot, render projectile
    if (status >= 0.) {
        co = minWithColor(co, sdBox(p, vec3(0.2,0.2,0.2), vec3(proj_pos) + vec3(-0.7,0.7,-1.0), proj_color, rotateY(proj_dir) * rotateX(proj_pitch / -q))); // q - coef from Buffer C
    }


    // Draw the trajectory as small squares
    drawTrajectory(
        tankPos + vec3(0.0, 0.675, 0.0),          // Start position
        tower_dir - 3.14/2.,             // Yaw angle
        -tower_pitch,       // Pitch angle
        10.0,                  // Initial velocity
        vec3(1.0, 0.5, 0.0),   // Trajectory color
        co,                    // Output Surface
        p                      // Current ray position
    );

    return co;
}
//===================================================================================

Surface rayMarch(vec3 ro, vec3 rd, float start, float end) {
  float depth = start;
  Surface co; // closest object

  for (int i = 0; i < MAX_MARCHING_STEPS; i++) {
    vec3 p = ro + depth * rd;
    co = sdScene(p);
    depth += co.sd;
    if (co.sd < PRECISION || depth > end) break;
  }

  co.sd = depth;

  return co;
}

vec3 calcNormal(in vec3 p) {
    vec2 e = vec2(1.0, -1.0) * 0.0005; // epsilon
    return normalize(
      e.xyy * sdScene(p + e.xyy).sd +
      e.yyx * sdScene(p + e.yyx).sd +
      e.yxy * sdScene(p + e.yxy).sd +
      e.xxx * sdScene(p + e.xxx).sd);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;
    vec3 backgroundColor = vec3(0.835, 1, 1);

    vec3 col = vec3(0);
    vec2 mouse = iMouse.xy / iResolution.xy - 0.5; // <-0.5,0.5>
    vec3 ro = vec3(uv.x, uv.y + 1.5, 7.);

    vec3 rd = normalize(vec3(uv * FOV, -1));
    rd *= rotateY(-mouse.x * MOUSE_SENS) * rotateX(mouse.y * MOUSE_SENS); // apply yaw and pitch

  Surface co = rayMarch(ro, rd, MIN_DIST, MAX_DIST); // closest object

  if (co.sd > MAX_DIST) {
    col = backgroundColor; // ray didn't hit anything
  } else {
    vec3 p = ro + rd * co.sd; // point on cube or floor
    vec3 normal = calcNormal(p);
    vec3 lightPosition = vec3(2., 2, 7.);
    vec3 lightDirection = normalize(lightPosition - p);

    float dif = clamp(dot(normal, lightDirection), WORLD_BRIGHTNESS, 1.); // diffuse reflection

    col = dif * co.col + backgroundColor * .2; // background color to the diffuse color
  }
  fragColor = vec4(col, 1.0);
}

