void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;


    float tower_dir = texelFetch(iChannel2, ivec2(0, 0), 0).x;
    float proj_dir = texelFetch(iChannel2, ivec2(0, 0), 0).y;
    vec3 pos = texelFetch(iChannel1, ivec2(0, 0), 0).yzw;

    float hit = texelFetch(iChannel2, ivec2(0, 0), 0).z;

    float status = texelFetch(iChannel1, ivec2(0, 0), 0).x;

    //SINGLE-TIME INIT WHEN FIRING
    if ((status <= 0.) && (texelFetch(iChannel0, ivec2(KEY_FIRE, 0), 0).x == 1.)) {
        status = 6.0;
        pos = vec3(0.7, -1, 0.7);
    }

    if (hit > 0.) {
        status = 0.;
    } 

    // xd-level simulation
    pos.x += sin(proj_dir) * speed;
    pos.z += -cos(proj_dir) * speed;

    float vert_speed = texelFetch(iChannel3, ivec2(0, 0), 0).x;

    pos.y += vert_speed * iTimeDelta;

    status -= iTimeDelta;

    if (iTime == 0.) {
        fragColor = vec4(-1,pos.x,pos.y,pos.z);
    } else { 
    //shot status, xyz projectile
    fragColor = vec4(status,pos.x,pos.y,pos.z);
    }
}

