// tower yaw rotation (left & right)
float l_border = -0.1;
float r_border = 0.6;
float speed = 0.005;
float hit;



void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;

    float left = texelFetch(iChannel0, ivec2(KEY_LEFT, 0), 0).x * -1.;    // get texels, texture coords, LoD
    float right = texelFetch(iChannel0, ivec2(KEY_RIGHT, 0), 0).x * 1.;
    float tower = texelFetch(iChannel2, ivec2(0, 0), 0).x;
    float proj = texelFetch(iChannel2, ivec2(0, 0), 0).y;
    if ((l_border <= tower) && (tower <= r_border)) {
        tower += speed * (left + right);
    }
    else if (l_border >= tower) {
        tower += speed * right;
    }
    else { tower += speed * left; }

    if (texelFetch(iChannel1, ivec2(0, 0), 0).x <= 0.) {
        proj = tower;  
    }

    float hitstatus = texelFetch(iChannel2, ivec2(0, 0), 0).w;

    vec3 pos = texelFetch(iChannel1, ivec2(0, 0), 0).yzw;
    //vec3( -iTime +5., -1, -25)
    hit = texelFetch(iChannel2, ivec2(0, 0), 0).z;
    if (hitstatus == 0. && ((((-iTime + 2. <= pos.x) && (pos.x <= -iTime + 8.)) && ((-26. <= pos.z) && (pos.z <= -24.)) && ((-3. <= pos.y) && (pos.y <= 0.5)))) || ((iTime >= 22.) && (iTime <=22.5))) {
        hit = 4.;
        //explosion status 1.5 sec
        hitstatus = 1.;
    } 
    hit -= iTimeDelta;

    if (iTime == 0.) {
        fragColor = vec4(0);
    } 
    else fragColor = vec4(tower,proj,hit,hitstatus); 
}

