// Коды клавиш
const int KEY_UP = 38;           // стрелка вверх
const int KEY_DOWN = 40;         // стрелка вниз
// Константы для движения и поворотов
const float MOVE_SPEED = 4.0;       // скорость движения танка
const float Frame = 1.0 / 90.0;     // время между кадрами
const float speed = 0.005;          // скорость изменения наклона башни

// Границы угла наклона башни
float l_border = -0.5;
float u_border = 0.1;

// Гравитация и параметры для башни
const float g = -5.5;
const float q = 15.;

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    ivec2 uv = ivec2(fragCoord);

    // Получение текущих данных о состоянии танка
    float vert_speed = texelFetch(iChannel3, ivec2(0, 0), 0).x;
    float tower_pitch = texelFetch(iChannel3, ivec2(0, 0), 0).y;
    float tankX = texelFetch(iChannel3, ivec2(0, 0), 0).z;
    float tankZ = texelFetch(iChannel3, ivec2(0, 0), 0).w;
    float tankAngle = texelFetch(iChannel3, ivec2(1, 0), 0).x;

    // Чтение состояния клавиш
    float down = texelFetch(iChannel0, ivec2(KEY_DOWN, 0), 0).x * -1.; // стрелка вниз
    float up = texelFetch(iChannel0, ivec2(KEY_UP, 0), 0).x * 1.;      // стрелка вверх

    // Управление наклоном башни
    if ((l_border <= tower_pitch) && (tower_pitch <= u_border)) {
        tower_pitch += speed * (down + up);
    } else if (l_border >= tower_pitch) {
        tower_pitch += speed * up;
    } else {
        tower_pitch += speed * down;
    }

    // Обработка вертикальной скорости
    if (texelFetch(iChannel0, ivec2(32, 0), 0).x == 1.) {
        vert_speed = -tower_pitch * q;
    }
    vert_speed += g * iTimeDelta;

    // Сохранение данных о танке
    if (uv.x == 0 && uv.y == 0) {
        fragColor = vec4(vert_speed, tower_pitch, tankX, tankZ); // сохраняем положение и угол башни
        return;
    }

    if (uv.x == 1 && uv.y == 0) {
        fragColor = vec4(tankAngle, 0.0, 0.0, 0.0); // сохраняем угол поворота танка
        return;
    }
}
